Solution
With a library that depends on the drivers only, the solution of the fitted equation is a cumulative sum of the predicted daily growth:

RPython


## coef: intercept and term coefficients; Theta_y: day x term (one season).
simulate &lt;- function(coef, Theta_y, y0) {
  rate &lt;- cbind(1, Theta_y[-nrow(Theta_y), ]) %*% coef
  y0 + c(0, cumsum(rate))
}


# coef: intercept and term coefficients; Theta_s: day x term (one season).
def simulate(coef, Theta_s, y0):
    rate = coef[0] + Theta_s[:-1] @ coef[1:]
    return y0 + np.concatenate([[0], np.cumsum(rate)])

Individual trajectories
Held-out prediction of the sparse model (STLSQ, fitted to the other seasons) and of the baseline for one genotype and season. Forty genotypes are available.

d3 = window.d3          // local copies, see js/
Plot = window.Plot
traj = FileAttachment("data/interactive/trajectories.json").json()
viewof genotype = select("Genotype", traj.genotypes, "g114")
viewof season = slider("Season", traj.years, traj.years.indexOf(1998))





































{
  const g = traj.genotypes.indexOf(genotype);
  const line = key =&gt; traj[key][g][season].map((y, i) =&gt; ({das: traj.das0 + i, y}));
  const [observed, model, baseline] = ["observed", "model", "baseline"].map(line);
  const rmse = a =&gt; Math.sqrt(d3.mean(a.slice(1), (d, i) =&gt; (d.y - observed[i + 1].y) ** 2));
  const plot = Plot.plot({
    width: 640, height: 320, marginLeft: 50,
    x: {label: "days after sowing"},
    y: {domain: [0, 18], label: "biomass (t/ha)"},
    marks: [
      Plot.line(observed, {x: "das", y: "y", stroke: "#9CA3AF", strokeWidth: 4}),
      Plot.line(baseline, {x: "das", y: "y", stroke: "#8B1E3F", strokeDasharray: "4 3"}),
      Plot.line(model, {x: "das", y: "y", stroke: "#014E81", strokeWidth: 2})
    ]
  });
  return html`${plot}&lt;p class="interactive-note"&gt;Grey: APSIM. Blue: model (RMSE ${rmse(model).toFixed(2)} t/ha). Dashed: baseline (RMSE ${rmse(baseline).toFixed(2)} t/ha).&lt;/p&gt;`;
}






